-- Purpose: original low-contrast neighborhood through shop windows. API: draw(x,y,w,h). Dependencies: outline/materials/theme/color/LÖVE.
local O=require('src.ui.draw.outline'); local T=require('src.ui.theme'); local C=require('src.ui.color'); local Street={}; local g=love.graphics
function Street.draw(x,y,w,h,progress) g.push('all'); g.translate(x,y); g.scale(w/1000,h/260); O.rect(0,0,1000,260,T.sky,0); local colors={T.blush,T.paper,T.teal,T.wood}; for i=0,5 do local bx=i*178-18; local by=34+(i%3)*18; local base=colors[i%4+1]; local wash={base[1]*.5+T.sky[1]*.5,base[2]*.5+T.sky[2]*.5,base[3]*.5+T.sky[3]*.5,1}; O.rect(bx,by,157,184,wash,1); O.polygon({bx-9,by,bx+78,by-26,bx+165,by},C.darken(wash,.08)); for window=0,2 do O.rect(bx+17+window*43,by+30,27,34,T.sky,2); O.line({bx+30+window*43,by+30,bx+30+window*43,by+64},C.darken(wash,.2),1) end; O.rect(bx+22,by+93,112,92,T.paper,1); for stripe=0,7 do g.setColor(stripe%2==0 and wash or T.paper); g.rectangle('fill',bx+14+stripe*16,by+88,16,15) end end; O.rect(0,220,1000,40,T.steel,0); O.line({0,244,1000,244},T.paper,1); O.line({0,19,300,39,650,14,1000,35},C.darken(T.sky,.28),1); O.line({0,31,400,56,1000,22},C.darken(T.sky,.22),.8)
 -- A small, original tricycle silhouette sits across the street.
 O.ellipse(806,238,15,15,T.bininner); O.ellipse(908,238,15,15,T.bininner); O.rect(821,190,83,47,T.teal,4); O.rect(843,164,58,28,T.paper,3); O.polygon({800,189,827,167,843,167,843,190},T.mustard); O.line({801,199,791,220,821,220},T.bininner,2); local dusk=math.max(0,math.min(1,((progress or 0)-.55)/.45)); if dusk>0 then g.setColor(T.plum[1],T.plum[2],T.plum[3],dusk*.22); g.rectangle('fill',0,0,1000,260) end; g.pop() end
return Street

